    # Hypothesis: A box opens with the key that matches its color.
    # Prior failures may be due to mechanical failure, not rule mismatch.
    return (key.color or "").lower() == (box.color or "").lower()"},{"time":4,"phase":"learning","keyName":"purple","doorName":"purple","correct":false,"supposed_to_open":0,"error":0,"hypothesis":"def predict(key, box) -> bool:
