    # Use the teacher's rule: a box opens with a key of the same color.
    try:
        return key.color == box.color
    except AttributeError:
        return False"},{"time":6,"phase":"learning","keyName":"purple","doorName":"purple","correct":false,"supposed_to_open":0,"error":0,"hypothesis":"def predict(key, box) -> bool:
    # Hypothesis: A box opens with a key of the same color.
    return key.color == box.color"},{"time":7,"phase":"learning","keyName":"heart","doorName":"purple","correct":false,"supposed_to_open":0,"error":0,"hypothesis":"def predict(key, box) -> bool:
    # Hypothesis:
    # - If the box's shape has a dedicated shape-key available (cloud, diamond, heart, triangle),
    #   then only the matching shape key opens the box.
    # - Otherwise (e.g., moon), the matching color key opens the box.
    shape_priority = {"cloud", "diamond", "heart", "triangle"}
    if box.shape in shape_priority:
        return key.shape == box.shape
    return key.color == box.color"},{"time":8,"phase":"learning","keyName":"red","doorName":"red","correct":false,"supposed_to_open":1,"error":1,"hypothesis":"def predict(key, box) -> bool:
    # Rule hypothesis:
    # - If the key has a shape, it opens the box with the same shape.
    # - If the key has no shape (numbered/color-only), it opens a box by color
    #   only when that box's shape has no matching shaped key available.
    # Known shapes present on keys:
    shapes_on_keys = {"cloud", "star", "heart", "triangle", "diamond", "arrow"}

    # If key has a shape, use shape-match rule.
    if key.shape is not None:
        return key.shape == box.shape

    # Key has no shape: allow color match only if the box's shape is not supported by any shaped key.
    # This avoids wasting attempts on boxes that should be opened by shaped keys.
    if key.shape is None:
        if box.shape not in shapes_on_keys:
            return key.color == box.color

    return False"},{"time":9,"phase":"learning","keyName":"triangle","doorName":"blue","correct":false,"supposed_to_open":0,"error":0,"hypothesis":"def predict(key, box) -> bool:
    # Hypothesis: Boxes open by a key matching their shape when such a key exists.
    # For the red box (moon shape, with no moon-shaped key), fall back to color match.
    box_to_key_id = {
        "red": "red",          # no moon-shaped key; use color
        "pink": "cloud",       # shape match
        "white": "diamond",    # shape match
        "purple": "heart",     # shape match
        "blue": "triangle",    # shape match
    }
    target_key_id = box_to_key_id.get(box.id)
    return key.id == target_key_id"},{"time":10,"phase":"learning","keyName":"pink","doorName":"pink","correct":false,"supposed_to_open":0,"error":0,"hypothesis":"def predict(key, box) -> bool:
    # Hypothesis: A box opens with the key that matches its color.
    return key.color == box.color"},{"time":11,"phase":"learning","keyName":"heart","doorName":"purple","correct":false,"supposed_to_open":0,"error":0,"hypothesis":"def predict(key, box) -> bool:
    # Prefer shape-matching keys for boxes whose shapes have matching keys.
    shape_priority = {"cloud", "diamond", "heart", "triangle"}
    if box.shape in shape_priority:
        return (key.shape is not None) and (key.shape == box.shape)
    # Otherwise, fall back to color-matching key.
    return key.color == box.color"},{"time":12,"phase":"learning","keyName":"white","doorName":"white","correct":false,"supposed_to_open":0,"error":0,"hypothesis":"def predict(key, box) -> bool:
    # Hypothesis: A box opens with the key that matches its color.
